// Nib: a thin tip runs ahead of the full stroke, so the line swells like ink from a fountain pen.
const NIB: [scale: number, lead: number][] = [[0.35, 0.036], [0.7, 0.018], [1, 0]];
const FULL: [scale: number, lead: number][] = [[1, 0]];

function Letters({ id, shapes, ink, nib, className }: { id: string; shapes: string[]; ink: Ink[]; nib: [number, number][]; className: string }) {
  return (
    <>
      {shapes.map((_, li) => (
        <g key={li} clipPath={`url(#${id}-${li})`} className={className}>
          {nib.map(([scale, lead]) =>
            ink.filter((b) => b[0] === li).map((b, i) => (
              <path
                key={`${scale}-${i}`}
                d={b[1]}
                pathLength={1}
                strokeWidth={scale === 1 ? b[2] : +(b[5] * scale).toFixed(1)}
                style={{ "--d": `${Math.max(0, b[3] - lead).toFixed(3)}s`, "--t": `${b[4]}s` } as CSSProperties}
              />
            )),
          )}
        </g>
      ))}
    </>
  );
}

export function Schriftzug({ className }: { className?: string }) {
  return (
    <svg className={`schriftzug${className ? ` ${className}` : ""}`} viewBox="307 604 1186 534" role="img" aria-label={SITE_NAME} focusable="false">
      <defs>
        {NAME.map((d, i) => <clipPath id={`sz-n-${i}`} key={`n${i}`}><path d={d} /></clipPath>)}
        {SUB.map((d, i) => <clipPath id={`sz-s-${i}`} key={`s${i}`}><path d={d} /></clipPath>)}
      </defs>
      <Letters id="sz-n" shapes={NAME} ink={NAME_INK} nib={NIB} className="schriftzug__ink schriftzug__ink--name" />
      <Letters id="sz-s" shapes={SUB} ink={SUB_INK} nib={FULL} className="schriftzug__ink schriftzug__ink--sub" />
    </svg>
  );
}
